WITH scored AS (SELECT id, full_name, email, manager_id, job_title, salary, hire_date, is_remote, SUM(salary) OVER (PARTITION BY job_title ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_salary, SUM(salary) OVER (PARTITION BY YEAR(hire_date), dept_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_salary_2 FROM employees WHERE full_name NOT LIKE 'Oli%'), matched_keys AS (SELECT id, manager_id FROM scored INTERSECT ALL SELECT id, manager_id FROM employees WHERE job_title IN ('Manager', 'Engineer')), kept_rows AS (SELECT s.* FROM scored s JOIN matched_keys k ON s.id = k.id AND s.manager_id = k.manager_id), scored_employees AS (SELECT *, DENSE_RANK() OVER (PARTITION BY job_title, manager_id ORDER BY running_salary_2) AS running_salary_2_dense_rank, DENSE_RANK() OVER (ORDER BY salary DESC) AS salary_dense_rank, CUME_DIST() OVER (PARTITION BY job_title ORDER BY running_salary DESC NULLS LAST) AS running_salary_cume_dist, ROUND(running_salary / SUM(running_salary) OVER (PARTITION BY manager_id, job_title), 4) AS running_salary_share FROM kept_rows), scored_employees_2 AS (SELECT id, full_name, job_title, salary, hire_date, is_remote, running_salary_2, running_salary_2_dense_rank, salary_dense_rank, running_salary_cume_dist, running_salary_share, PERCENT_RANK() OVER w_ordered AS running_salary_share_percent_rank, ROUND(salary_dense_rank / SUM(salary_dense_rank) OVER (PARTITION BY manager_id), 4) AS salary_dense_rank_share FROM scored_employees WINDOW w_ordered AS (ORDER BY running_salary_share DESC NULLS LAST)) SELECT job_title, salary, hire_date, running_salary_2, running_salary_2_dense_rank, salary_dense_rank, running_salary_cume_dist, running_salary_share, salary_dense_rank_share, CASE WHEN job_title RLIKE '^(Manager|Designer)$' THEN 'EXTENDED' ELSE 'CORE' END AS job_title_zone FROM scored_employees_2 ORDER BY salary DESC NULLS FIRST, job_title
